/**
 * @ohos/dsh-credentials-live — hot API-key updates for HarmonyOS.
 *
 * dsh freezes its launch environment (including DEEPSEEK_API_KEY) at boot:
 * the launch-environment snapshot is a boot-time copy of process.env, so a
 * key saved in Settings while the app runs never reaches the running runtime,
 * and the credentials-local provider's chokidar watcher cannot be relied
 * upon here (inotify availability in the app sandbox is unverified). This
 * plugin closes that seam for the `ohos` profile:
 *
 *   - the app keeps writing the current key to `<dsh-home>/.api-key`
 *     (NodeHost at boot, AppConfig.save mid-session; atomic temp+rename, so
 *     a concurrent reader never observes a torn value);
 *   - this plugin watches that file and, on change, pushes the value through
 *     the credentials service — `set()`/`unset()` update the provider's live
 *     snapshot and publish to listeners directly, no watcher needed on the
 *     store side;
 *   - a directory-level `fs.watch` fast path is attached when the platform
 *     supports it; the interval poll remains the correctness backstop either
 *     way.
 *
 * Effect: saving a key in Settings takes effect within ~intervalMs without
 * restarting the app (ACP/ohos profile). Clearing the key clears the store
 * immediately; the boot-time env fallback (frozen at launch) disappears on
 * the next app start, when bootstrap no longer seeds the variable.
 *
 * Reconciliation is idempotent and value-driven: an unchanged file value is
 * skipped, and a value that already matches the resolved credential is
 * adopted without writing (so boot-time sync with an already-seeded env
 * stays silent).
 */
import { watch } from "node:fs";
import { readFile } from "node:fs/promises";
import { basename, dirname, join } from "node:path";
import { resolveDshHome } from "@deepseek-ai/dsh-home-paths";
import z from "@deepseek-ai/schemastery";

const name = "credentials-live-ohos";
const inject = ["credentials"];

const LOG_TAG = "[credentials-live]";

const Config = z.object({
	/** Poll cadence for the staged key file; the poll is the backstop path. */
	intervalMs: z.number().default(1500),
	/** Staged key file watched for updates; empty selects `<dsh-home>/.api-key`. */
	keyFile: z.string().default(""),
	/** Credential reference hot-updated; matches the llm-deepseek-api-key route. */
	envName: z.string().default("DEEPSEEK_API_KEY")
});

/** Read the staged key, trimmed; a missing file is an empty value. */
async function readStagedKey(keyFile) {
	try {
		return (await readFile(keyFile, "utf8")).trim();
	} catch (error) {
		if (error?.code === "ENOENT") return "";
		throw error;
	}
}

/**
 * One reconciliation pass: push the staged key into the credentials store.
 * `seen.value` is only advanced after a successful store write, so a failed
 * set/unset retries on the next tick instead of being forgotten.
 * @returns the action taken: "same" | "adopt" | "set" | "unset".
 */
async function syncOnce(credentials, keyFile, envName, seen) {
	const value = await readStagedKey(keyFile);
	if (value === seen.value) return "same";
	const resolved = await credentials.resolve(envName);
	if ((resolved?.value ?? "") === value) {
		seen.value = value;
		return "adopt";
	}
	if (value.length === 0) {
		await credentials.unset(envName);
		seen.value = value;
		return "unset";
	}
	await credentials.set(envName, value);
	seen.value = value;
	return "set";
}

function apply(ctx, config) {
	const keyFile = config.keyFile.length > 0 ? config.keyFile : join(resolveDshHome(), ".api-key");
	const seen = { value: undefined };
	let syncing = false;
	const sync = async () => {
		if (syncing) return;
		syncing = true;
		try {
			const action = await syncOnce(ctx.credentials, keyFile, config.envName, seen);
			if (action === "set") console.log(`${LOG_TAG} key updated (hot)`);
			else if (action === "unset") console.log(`${LOG_TAG} key cleared`);
		} catch (error) {
			console.error(`${LOG_TAG} sync failed: ${error?.message ?? error}`);
		} finally {
			syncing = false;
		}
	};
	// Fast path: directory-level fs.watch survives create/rename of the staged
	// file; the interval poll backstops platforms where fs.watch is inert.
	let watcher;
	let watched = false;
	try {
		watcher = watch(dirname(keyFile), { persistent: false }, (_event, filename) => {
			if (filename === basename(keyFile)) void sync();
		});
		watcher.on("error", () => {});
		watched = true;
	} catch {
		watcher = undefined;
	}
	const timer = setInterval(() => {
		void sync();
	}, config.intervalMs);
	if (typeof timer.unref === "function") timer.unref();
	ctx.effect(() => () => {
		clearInterval(timer);
		try {
			watcher?.close();
		} catch {
			// closing an errored watcher may throw; disposal stays best-effort
		}
	}, "credentials-live: staged-key poll");
	console.log(`${LOG_TAG} watching ${keyFile} (${watched ? "dir-watch + " : ""}poll every ${config.intervalMs}ms)`);
	void sync();
}

export { Config, apply, inject, name, readStagedKey, syncOnce };
